#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string reformatNumber(string number) {
        string digits = "";
        for (char c : number) {
            if (isdigit(c)) digits += c;
        }
        string res = "";
        int i = 0, n = digits.size();
        while (n - i > 4) {
            if (!res.empty()) res += '-';
            res += digits.substr(i, 3);
            i += 3;
        }
        if (n - i == 4) {
            if (!res.empty()) res += '-';
            res += digits.substr(i, 2);
            res += '-';
            res += digits.substr(i + 2, 2);
        } else {
            if (!res.empty()) res += '-';
            res += digits.substr(i);
        }
        return res;
    }
};

class Solution {
    public String reformatNumber(String number) {
        StringBuilder sb = new StringBuilder();
        for (char c : number.toCharArray()) {
            if (Character.isDigit(c)) sb.append(c);
        }
        String digits = sb.toString();
        StringBuilder res = new StringBuilder();
        int i = 0, n = digits.length();
        while (n - i > 4) {
            if (res.length() > 0) res.append('-');
            res.append(digits, i, i + 3);
            i += 3;
        }
        if (n - i == 4) {
            if (res.length() > 0) res.append('-');
            res.append(digits, i, i + 2);
            res.append('-');
            res.append(digits, i + 2, i + 4);
        } else {
            if (res.length() > 0) res.append('-');
            res.append(digits.substring(i));
        }
        return res.toString();
    }
}

